import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    env_config = {k[len(env_prefix) + 1:].replace('__', '.').lower(): v for k, v in env_mapping.items() if k.startswith(env_prefix)}
    for key, value in env_config.items():
        parts = key.split('.')
        current = config
        for part in parts[:-1]:
            if part not in current:
                current[part] = {}
            current = current[part]
        current[parts[-1]] = value
    return config

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    assert load_config(defaults) == {'key': 'value'}

def test_toml():
    toml_content = b'key = "value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    assert load_config({}, 'config.toml') == {'key': 'value'}

def test_env():
    os.environ['APP__KEY'] = 'value'
    assert load_config({}, env_prefix='APP') == {'key': 'value'}

def test_precedence():
    toml_content = b'key = "toml_value"'
    os.environ['APP__KEY'] = 'env_value'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    assert load_config({'key': 'default_value'}, 'config.toml', env_prefix='APP') == {'key': 'env_value'}

def test_coercion():
    os.environ['APP__INT'] = '123'
    os.environ['APP__FLOAT'] = '45.6'
    os.environ['APP__BOOL'] = 'true'
    assert load_config({'int': 0, 'float': 0.0, 'bool': False}, env_prefix='APP') == {'int': 123, 'float': 45.6, 'bool': True}

def test_error():
    os.environ['APP__UNKNOWN'] = 'value'
    with pytest.raises(ConfigError):
        load_config({}, env_prefix='APP')
